use std::f64::consts::PI;
fn main(){
  let n: i32 = std::env::args().nth(1).unwrap().parse().unwrap();
  let mut layer: i32 = 0;
  while layer < n {
    let radius = layer.wrapping_add(1) as f64 * 0.3;
    let count = layer.wrapping_add(3).wrapping_mul(2);
    let mut i: i32 = 0;
    while i < count {
      let angle = 2.0 * PI * i as f64 / count as f64;
      let offset = layer as f64 * 0.1;
      println!("{} {} {:016x} {:016x} {:016x}", layer, i, angle.to_bits(),
        ((radius + offset) * angle.cos()).to_bits(),
        ((radius + offset) * angle.sin()).to_bits());
      i += 1;
    }
    layer = layer.wrapping_add(1);
  }
}
EOF
